begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions;
select no_plan();
insert into auth.users(id,email) values('73000000-0000-0000-0000-000000000001','prefs-a@example.test'),('73000000-0000-0000-0000-000000000002','prefs-b@example.test');
set local role authenticated;
set local "request.jwt.claim.sub"='73000000-0000-0000-0000-000000000001';
select is((select time_zone from public.profiles),'UTC','Existing default stays explicit UTC');
select ok((select time_zone_confirmed_at is null from public.profiles),'UTC is not silently confirmed');
select is(public.save_account_preferences(1,'83000000-0000-0000-0000-000000000001','{"time_zone":"UTC","cosmic_enabled":false,"zodiac_sign":"virgo"}'),2::bigint,'Confirm and save supported preferences atomically');
select ok((select time_zone_confirmed_at is not null from public.profiles),'Explicit confirmation records server timestamp');
select is(public.save_account_preferences(1,'83000000-0000-0000-0000-000000000001','{"time_zone":"UTC","cosmic_enabled":false,"zodiac_sign":"virgo"}'),2::bigint,'Ambiguous retry is idempotent');
select throws_ok($$select public.save_account_preferences(1,gen_random_uuid(),'{"cosmic_enabled":true}')$$,'40001',null,'Stale preference save rejected');
select throws_ok($$select public.save_account_preferences(2,gen_random_uuid(),'{"time_zone":"Bad/Zone"}')$$,'22023',null,'Invalid zone rejected');
select throws_ok($$select public.save_account_preferences(2,gen_random_uuid(),'{"cosmic_enabled":"true"}')$$,'22023',null,'Forecast enabled must be boolean');
select throws_ok($$select public.save_account_preferences(2,gen_random_uuid(),'{"zodiac_sign":"unknown"}')$$,'22023',null,'Unsupported sign rejected');
select throws_ok($$select public.save_account_preferences(2,gen_random_uuid(),'{"id":"73000000-0000-0000-0000-000000000002"}')$$,'22023',null,'Caller cannot choose another owner');
select throws_ok($$update public.profiles set time_zone='Asia/Tokyo'$$,'42501',null,'Direct zone updates cannot bypass revision checks');
select public.save_daily_record('2026-03-08','{"intention_text":"Original day"}',(public.ensure_daily_record('2026-03-08')).revision);
select is(jsonb_array_length(public.export_personal_data()->'daily_records'),1,'Export includes own persisted days');
select is(public.export_personal_data()#>>'{profile,zodiac_sign}','virgo','Export includes saved preferences');
select ok(not public.export_personal_data()?'preference_commands','Private command infrastructure excluded');
set local "request.jwt.claim.sub"='73000000-0000-0000-0000-000000000002';
select is((select count(*)::integer from public.profiles),1,'User sees only own profile');
select is(jsonb_array_length(public.export_personal_data()->'daily_records'),0,'Export excludes another account data');
set local role anon;
select throws_ok($$select public.export_personal_data()$$,'42501',null,'Anonymous export denied');
select throws_ok($$select public.save_account_preferences(1,gen_random_uuid(),'{"cosmic_enabled":false}')$$,'42501',null,'Anonymous preference mutation denied');
reset role;
select * from finish();rollback;
